    const hasLayers=!!st.s1&&!!st.s2, hasDensity=!!(n(st.s1?.bulk_density_g_cm3)||n(p.bulk_density_default))&&!!(n(st.s2?.bulk_density_g_cm3)||n(p.bulk_density_default));
    const sampleDate=st.sampleDate, sampleAge=sampleDate?daysBetween(sampleDate):999;
