    const etoTotal=observedEt0>0?observedEt0:elapsed*n(climate.eto);
    const rainTotal=wx.reduce((s,x)=>s+n(x.rain_mm),0);
    const irrigationTotal=irr.reduce((s,x)=>s+n(x.millimeters||x.mm),0);
