    const rateInfo=applicationRate(lot,p),rate=rateInfo.value;
    const profileReady=!!p.id&&baseKc>0&&n(p.irrigation_efficiency_pct)>0&&n(p.rain_efficiency_pct)>0&&n(p.refill_trigger_pct)>0&&n(p.deep_reserve_pct)>0;
    const calculationReady=profileReady&&hasLayers&&hasDensity&&!!st.root.planting&&etoAvailable;
