    let status='Sin datos suficientes',css='warn';
    if(ready){if(occupancy<=trigger){status='Regar hoy';css='bad';}else if(occupancy<=trigger+10){status='Regar en 24–48 h';css='warn';}else if(occupancy<=trigger+20){status='Vigilar';css='warn';}else{status='No regar';css='';}if(!calculationReady)status+= ' · estimado';}
    const ndvi=n(lastSatellite?.ndvi||lastAnalysis?.ndvi_avg||lastObs?.ndvi),ndmi=n(lastObs?.ndmi||lastAnalysis?.ndmi_avg);
    const satelliteDate=lastSatellite?.observed_to||lastSatellite?.observed_from||lastAnalysis?.flight_date||lastObs?.observation_date;
    const satelliteAge=satelliteDate?daysBetween(satelliteDate):999;
    const stationLatest=(state.weatherStationObservations||[]).slice().sort((a,b)=>String(b.observed_at||b.observation_date||'').localeCompare(String(a.observed_at||a.observation_date||'')))[0];
    const stationAge=stationLatest?daysBetween(stationLatest.observed_at||stationLatest.observation_date):999;
    const irrigationAge=lastIrr?daysBetween(lastIrr.event_date||lastIrr.irrigation_date):999;
