    const sourceParts=['Suelo franco limoso confirmado: 320 mm/200 cm',`capacidad radicular ${number(st.capacity,1)} mm a ${number(st.depth,0)} cm`,'Muestra gravimétrica',`siembra ${st.root.planting||'sin fecha'}`,`ETc acumulada desde muestra ${number(etc,1)} mm`];if(lastSatellite)sourceParts.push(`satélite ${dateOnly(lastSatellite.observed_to||lastSatellite.observed_from)}`);sourceParts.push(wx.length?'estación propia':climate.hasEto?'ET₀ Open-Meteo':'ET₀ pendiente');
