    const samples=(state.gravimetricSamples||[]).filter(e=>sameId(e.lot_id,x.lot.id)&&isValidOperationalDate(e.sample_date)).map(e=>({date:e.sample_date,type:'Muestra',icon:'🧪',detail:`${escapeHtml(e.layer_code||`${e.depth_from_cm||0}–${e.depth_to_cm||0} cm`)} · ${number(e.gravimetric_moisture_pct,1)}%`}));
